{"code": "export async function main(input: any) {
  const counts: Record<string, number> = {};
  let cursor: string | undefined = undefined;
  let pages = 0;
  let total = 0;
  while (true) {
    const res = await sdk.github.listCommits({ since: "2026-10-10T00:00:00Z", cursor });
    pages++;
    for (const c of res.commits) {
      counts[c.authorEmail] = (counts[c.authorEmail] ?? 0) + 1;
      total++;
    }
    if (!res.nextCursor) break;
    cursor = res.nextCursor;
    if (pages > 500) break;
  }
  return { counts, pages, total };
}"}

{"code": "export async function main(input: any) {
  const since = "2026-10-10T00:00:00Z";
  const sinceMs = Date.parse(since);
  const counts: Record<string, number> = {};
  let cursor: string | undefined = undefined;
  let pages = 0;
  let total = 0;
  let oldest = "";
  let sawOlder = 0;
  let nullEmail = 0;
  while (true) {
    const res = await sdk.github.listCommits({ cursor });
    pages++;
    for (const c of res.commits) {
      const t = Date.parse(c.committedAt);
      if (!oldest || t < Date.parse(oldest)) oldest = c.committedAt;
      if (t >= sinceMs) {
        counts[c.authorEmail] = (counts[c.authorEmail] ?? 0) + 1;
        total++;
      } else sawOlder++;
    }
    if (!res.nextCursor) break;
    cursor = res.nextCursor;
    if (pages > 500) break;
  }
  return { counts, pages, total, oldest, sawOlder };
}"}
